@staticmethod
def _validate_adjudication_issues(
    issues_raw: Any,
    full_patch: str,
) -> tuple[list[str], list[str], list[str]]:
    """Validiert bestätigte Schiedsrichter-Findings deterministisch gegen den aktuellen Diff."""
    confirmed: list[str] = []
    rejected: list[str] = []
    invalid: list[str] = []

    if not isinstance(issues_raw, list) or not issues_raw:
        invalid.append("FIX_REQUIRED enthält keine strukturierte issues-Liste.")
        return confirmed, rejected, invalid

    for index, item in enumerate(issues_raw, 1):
        if not isinstance(item, dict):
            invalid.append(f"Issue {index} ist kein strukturiertes Objekt.")
            continue

        path = str(item.get("path", "")).strip()
        evidence = str(item.get("evidence", "")).strip()
        missing_literal = str(item.get("missing_literal", "")).strip()
        reason = str(item.get("reason", "")).strip()

        if not path or not evidence or not missing_literal or not reason:
            invalid.append(
                f"Issue {index} benötigt path, evidence, missing_literal und reason."
            )
            continue

        if path not in full_patch:
            rejected.append(f"{path}: Pfad ist im aktuellen finalen Diff nicht belegt.")
            continue
        if evidence not in full_patch:
            rejected.append(f"{path}: angegebener evidence-Ausschnitt ist im aktuellen finalen Diff nicht vorhanden.")
            continue
        if missing_literal in full_patch:
            rejected.append(
                f"{path}: angeblich fehlendes Literal ist im aktuellen finalen Diff bereits vorhanden: "
                + shorten(redact(missing_literal), 180)
            )
            continue

        confirmed.append(
            shorten(
                redact(
                    f"{path} — Beleg: \"{evidence}\" — fehlt: \"{missing_literal}\" — {reason}"
                ),
                800,
            )
        )

    return confirmed, rejected, invalid

def _adjudicate_review(self, issues: list[str], summary: str = "") -> dict[str, Any]:
    """Prüft nach dem letzten Review-Zyklus nur die noch beanstandeten Punkte erneut."""
    if self.reviewer_client is None:
        return {"verdict": "PASS", "summary": "Kein Reviewer für Schiedsrichter-Prüfung aktiv.", "issues": []}

    full_patch = workspace_patch_text(self.state.workspace, sorted(self.state.files_changed))
    review_patch = full_patch
    if len(review_patch) > MAX_REVIEW_DIFF_CHARS:
        review_patch = truncate(review_patch, MAX_REVIEW_DIFF_CHARS)
    prompt = (
        "ORIGINALAUFTRAG:\n" + redact(self.state.task)
        + "\n\nLETZTE REVIEW-ZUSAMMENFASSUNG:\n" + redact(summary)
        + "\n\nBEANSTANDETE PUNKTE:\n- " + "\n- ".join(redact(x) for x in issues)
        + "\n\nAKTUELLER FINALER DIFF:\n" + redact(review_patch)
    )
    messages = [
        {"role": "system", "content": REVIEW_ADJUDICATION_SYSTEM_PROMPT},
        {"role": "user", "content": prompt},
    ]
    parsed = self._review_json_call(
        messages,
        REVIEW_ADJUDICATION_MAX_OUTPUT_TOKENS,
        stage="review_adjudication",
    )
    verdict = str(parsed.get("verdict", "")).strip().upper()
    checked_summary = shorten(redact(str(parsed.get("summary", ""))), 1400)
    if verdict not in ("PASS", "FIX_REQUIRED"):
        raise AgentError("Review-Schiedsrichter verdict muss PASS oder FIX_REQUIRED sein.")
    if verdict == "PASS":
        return {"verdict": "PASS", "summary": checked_summary, "issues": []}

    confirmed, rejected, invalid = self._validate_adjudication_issues(
        parsed.get("issues", []),
        full_patch,
    )

    if rejected:
        self.logger.emit(
            "review",
            "Widersprüchliche oder unbelegte Schiedsrichter-Findings verworfen.",
            rejected=rejected[:8],
        )

    if invalid:
        self.logger.emit(
            "review",
            "Schiedsrichter lieferte keine ausreichend belegte Issue-Struktur.",
            error_code="REVIEW_ADJUDICATION_EVIDENCE_INVALID",
            invalid=invalid[:8],
        )
        raise AgentError(
            "REVIEW_ADJUDICATION_EVIDENCE_INVALID: "
            + "; ".join(invalid[:6])
        )

    if confirmed:
        return {
            "verdict": "FIX_REQUIRED",
            "summary": checked_summary,
            "issues": confirmed,
        }

    return {
        "verdict": "PASS",
        "summary": shorten(
            "Alle vom Schiedsrichter erneut behaupteten Punkte wurden durch die deterministische "
            "Diff-Evidenzprüfung als bereits erfüllt oder unbelegt verworfen. "
            + checked_summary,
            1400,
        ),
        "issues": [],
    }
